-- Contraseña de la cuenta demo (para el botón "Entrar con la cuenta demo"; ver README).
update auth.users set encrypted_password = crypt('demo-trato-2026', gen_salt('bf')), email_confirmed_at = coalesce(email_confirmed_at, now()) where id = '00000000-0000-4000-8000-00000000d3a0';
do $$ begin
  values (gen_random_uuid(), '00000000-0000-4000-8000-00000000d3a0', '{"sub":"00000000-0000-4000-8000-00000000d3a0","email":"demo@trato.mx"}', 'email', '00000000-0000-4000-8000-00000000d3a0', now(), now(), now())
  on conflict do nothing;
exception when others then null; end $$;

update public.profiles set display_name = 'Vendedor Demo', phone = '+525512345678', phone_verified = true,
  state = 'ciudad-de-mexico', city = 'Ciudad de México' where id = '00000000-0000-4000-8000-00000000d3a0';

delete from public.listings where user_id = '00000000-0000-4000-8000-00000000d3a0';


-- Anuncios destacados de ejemplo: 2 autos y 1 moto (los más caros), durante 15 días desde que cargas este archivo.
update public.listings set boosted_until = now() + interval '15 days' where id in (select id from public.listings where user_id = '00000000-0000-4000-8000-00000000d3a0' and vehicle_type = 'auto' order by price_mxn desc limit 2);
update public.listings set boosted_until = now() + interval '15 days' where id in (select id from public.listings where user_id = '00000000-0000-4000-8000-00000000d3a0' and vehicle_type = 'moto' order by price_mxn desc limit 1);

